{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Melagatran, a highly polar ionizable direct thrombin inhibitor, has human oral bioavailability of only 0.9–7%, demonstrating that extensive ionization and polar functionality can severely limit F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Remikiren, a peptidomimetic renin inhibitor with high molecular weight and multiple amide bonds, has absolute oral bioavailability of 0.2–0.3% in humans across doses, indicating severe first-pass and absorption limitations.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Nintedanib, a heteroaromatic kinase inhibitor, has absolute oral bioavailability of approximately 5% in healthy volunteers, attributed to rapid metabolism and poor absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Rebamipide, which contains a quinolinone-like core, has human oral bioavailability under 10%, supporting low F for the query's quinolinone-containing scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "DX-9065a, a factor Xa inhibitor with strongly basic amidine groups, has human oral bioavailability of only 2–3%, showing that basic ionizable groups can severely limit oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "MK-458 has absolute oral bioavailability of approximately 4–5% in patients, another example of a moderately sized drug with low F due to first-pass metabolism.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All highly transferable experimental analogues show low absolute oral bioavailability, mostly below 10%, with the only borderline case (retosiban, 17–25%) straddling the threshold and not outweighing the consistent low-F evidence. The query's large size, high TPSA, and very low neutral fraction are consistent with poor permeability and extensive first-pass elimination, strongly supporting F < 20%.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule; prediction relies on highly transferable analogues.",
    "Retosiban's F range of 17–25% straddles the 20% threshold, adding some uncertainty.",
    "The query's specific transporter interactions and metabolic stability are unknown; active efflux or first-pass metabolism could further lower F."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

